def generate_ignored_nodes(leaf: Leaf) -> Iterator[LN]:
    """Starting from the container of `leaf`, generate all leaves until `# fmt: on`.

    Stops at the end of the block.
    """
    container: Optional[LN] = container_of(leaf)
    is_fmt_on = False
    while container is not None and container.type!= token.ENDMARKER:
        for comment in list_comments(container.prefix, is_endmarker=False):
            if comment.value in FMT_ON:
                is_fmt_on = True
            elif comment.value in FMT_OFF:
                is_fmt_on = False
        if is_fmt_on:
            return

        yield container

        # Move to the next sibling
        container = container.next_sibling

        # Check if the next sibling is a multi-line node
        if hasattr(container, 'children'):
            for child in container.children:
                if child.type == token.INDENT:
                    # If it's an INDENT node, move to the next child
                    container = child.next_sibling
                    break

        # If we've reached the end of a block, stop
        if container.type in [token.DEDENT, token.ENDMARKER]:
            break
