```python
def generate_ignored_nodes(leaf: Leaf) -> Iterator[LN]:
    """Starting from the container of `leaf`, generate all leaves until `# fmt: on`.

    Stops at the end of the block.
    """
    container: Optional[LN] = container_of(leaf)
    is_fmt_on = False
    while container is not None and container.type!= token.ENDMARKER:
        for comment in list_comments(container.prefix, is_endmarker=False):
            if comment.value in FMT_ON:
                is_fmt_on = True
            elif comment.value in FMT_OFF:
                is_fmt_on = False
        if is_fmt_on:
            return

        yield container

        # Move to the next sibling, considering the block structure
        if container.type == token.INDENT:
            # If the current node is an indent, move to its parent
            container = container.parent
        else:
            container = container.next_sibling

        # If the current node is a decorator, move to the next decorator or the function definition
        while container is not None and container.type == token.AT:
            container = container.next_sibling
        if container is not None and container.type == token.DEF:
            # If the current node is a function definition, move to its first child
            container = container.children[0]
